#!/usr/bin/env bash
# C++ / CMake, one own_tests target built from every tests/own/*.cpp.
#
# Rendered from the [runner] table in task.toml by `ninny runner --write`. Do not edit this file
# by hand: `ninny runner --check` fails when it differs from its config, and the gate runs that.
#
# The exit code is the contract the harness reads, so each code means exactly one thing:
#   0  the tests ran and passed
#   1  the tests ran and failed          -- a RED observation
#   2  nothing ran                       -- nothing was observed, so not a RED either
#
# A build error, an empty suite and a suite that asserts nothing are all 2: none of them
# observed a failing test. tools/ is not the agent's to edit.
# The frozen CMakeLists.txt compiles every tests/own/*.cpp together with every src/*.cpp into
# one target, so a new case is a new file and nothing else. The harness prints
# "<label>: N checked, M failed" whatever label the author chose, and "0 checked, 0 failed" is a
# suite that asserted nothing -- exit 2, not a pass.
#
set -uo pipefail
here=$(cd "$(dirname "$0")" && pwd)

if [ -n "${NINNY_RUNNER_REPLAY:-}" ]; then
  # A recorded transcript, so the corpus can test this script without a toolchain. Read it
  # BEFORE moving into the tree, so the path stays the caller's to give -- relative or absolute.
  out=$(cat "$NINNY_RUNNER_REPLAY" 2>&1)
  rc=${NINNY_RUNNER_REPLAY_RC:-0}
else
  cd "$here/.." || exit 2
  if ! ls tests/own/*.cpp >/dev/null 2>&1; then
    echo "nothing to run yet: no tests/own/*.cpp -- write one case that fails because
           the behaviour is not there, then run this again."
    echo "NINNY_TESTS: 0"
    exit 2
  fi
  cmake -S . -B build -DCMAKE_BUILD_TYPE=Debug && cmake --build build --target own_tests > build.log 2>&1
  if [ $? -ne 0 ]; then
    echo "BUILD FAILED -- nothing was built and nothing ran, so this is exit 2."
    tail -20 build.log
    echo "NINNY_TESTS: 0"
    exit 2
  fi
  out=$(./build/own_tests 2>&1)
  rc=$?
fi

# --- the verdict, in one order, for every toolchain
n0=$(printf '%s\n' "$out" | grep -oE '.*: ([0-9]+) checked,' | sed -E 's/.*: ([0-9]+) checked,/\1/' | awk '{t += $1} END {print t + 0}')

count=$(( 0 + n0 ))

# The count is evidence even when it is zero: the record needs to know whether a run
# collected nothing or failed on something, so it is always printed.
echo "NINNY_TESTS: $count"

# Zero cases means nothing was observed -- a build that succeeds is not a suite that
# asserts, and a suite that collects nothing is not a red. Same rule, every toolchain.
if [ "$count" -eq 0 ]; then
  echo "no test cases ran at all -- nothing was observed, so this is exit 2 and not a RED"
  exit 2
fi

if [ "$rc" -ne 0 ]; then
  exit 1
fi
exit 0
